INSERT INTO itineraries (id, tour_id, day_num, title, date, weather_mock) VALUES
(1, 'JP-TFK-0924', 1, 'สุวรรณภูมิ - บินสู่นาริตะ - เมืองชินจูกุ - เข้าโรงแรม', 'พฤหัสบดีที่ 15 ตุลาคม 2569', 'โตเกียว: 18°C ☀️ อากาศเย็นและแจ่มใส'),
(2, 'JP-TFK-0924', 2, 'วัดอาซากุสะ - ถนนนากามิเสะ - โตเกียวสกายทรี - ย่านชิบูย่า', 'ศุกร์ที่ 16 ตุลาคม 2569', 'โตเกียว: 17°C ☁️ เมฆบางส่วน'),
(3, 'JP-TFK-0924', 3, 'โตเกียว - ภูเขาไฟฟูจิ (ชั้น 5) - ศาลเจ้าอาราคูระเซนเกน - ออนเซ็น', 'เสาร์ที่ 17 ตุลาคม 2569', 'ฟูจิ/คาวากุจิโกะ: 12°C ☀️ ฟ้าเปิด เห็นฟูจิชัดเจน'),
(4, 'JP-TFK-0924', 4, 'ฟูจิ - นั่งรถไฟด่วนชินคันเซ็นสู่เกียวโต - วัดคินคะคุจิ - เข้าโรงแรมเกียวโต', 'อาทิตย์ที่ 18 ตุลาคม 2569', 'เกียวโต: 20°C 🌤️ อากาศเย็นสบาย'),
(5, 'JP-TFK-0924', 5, 'ศาลเจ้าฟูชิมิอินาริ - วัดน้ำใสคิโยมิสึ - ย่านกิออน', 'จันทร์ที่ 19 ตุลาคม 2569', 'เกียวโต: 19°C ☀️ แดดตลอดวัน ลมโชยเย็น'),
(6, 'JP-TFK-0924', 6, 'เกียวโต - ห้างอิออน มอลล์ - สนามบินคันไซ - กรุงเทพฯ', 'อังคารที่ 20 ตุลาคม 2569', 'โอซาก้า/คันไซ: 21°C 🌧️ มีฝนเล็กน้อยในช่วงเย็น');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(1, '05:15 น.', 'พร้อมกันที่สนามบินสุวรรณภูมิ เช็คอินเคาน์เตอร์ JAL', 'สนามบินสุวรรณภูมิ ชั้น 4 แถว R', 'หัวหน้าทัวร์แจกซองเอกสาร ป้ายห้อยกระเป๋า และใบ ตม. ญี่ปุ่น (กรณีไม่ได้กรอกออนไลน์)', 'เช็คว่าลูกทัวร์ทุกคนมี QR Code สำหรับเข้าประเทศ (Visit Japan Web) ครบถ้วน เพื่อความรวดเร็วที่ ตม. นาริตะ'),
(1, '08:15 น.', 'ออกเดินทางสู่สนามบินนาริตะ เที่ยวบิน JL728', 'บนเที่ยวบิน JL728', 'บริการอาหารและเครื่องดื่มบนเครื่องบิน (ใช้เวลาบินประมาณ 6 ชั่วโมง)', 'เดินดูแลความเรียบร้อย แจ้งลูกทัวร์เรื่องการปรับเวลา (เวลาญี่ปุ่นเร็วกว่าไทย 2 ชั่วโมง)'),
(1, '16:25 น.', 'เดินทางถึงสนามบินนาริตะ ผ่านพิธีตรวจคนเข้าเมือง', 'สนามบินนาริตะ อาคารผู้โดยสาร 2', 'ผ่านด่าน ตม. และรับกระเป๋าสัมภาระ จากนั้นพบไกด์ท้องถิ่นและคนขับรถบัส', 'นับจำนวนกระเป๋าและลูกทัวร์ให้ครบที่จุดนัดพบ เช็คสภาพรถบัสและป้ายต้อนรับด้านหน้ากระจกรถ'),
(1, '18:00 น.', 'เดินทางสู่ย่านชินจูกุโดยรถบัสปรับอากาศ', 'ย่านชินจูกุ (Shinjuku)', 'ชมทัศนียภาพยามค่ำคืนของโตเกียว', 'อธิบายแผนการเดินทางของวันพรุ่งนี้และรายละเอียดโรงแรมบนรถบัส'),
(1, '19:30 น.', 'รับประทานอาหารค่ำ (เบนโตะพรีเมียมบนรถบัส) และเช็คอินโรงแรม', 'โรงแรม Shinjuku Granbell Hotel', 'จ่ายกุญแจห้องพักผ่อนตามอัธยาศัย', 'ประสานงานกับเคาน์เตอร์โรงแรมล่วงหน้าเพื่อรับ Room Keys ทั้งหมด นัดหมายเวลาล้อหมุนพรุ่งนี้เช้า 08:30 น.');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(2, '07:30 น.', 'รับประทานอาหารเช้า ณ ห้องอาหารของโรงแรม', 'ห้องอาหารชั้น 12 Shinjuku Granbell', 'บุฟเฟต์นานาชาติและอาหารเช้าสไตล์ญี่ปุ่น', 'เดินตรวจดูว่าลูกทัวร์ลงมาทานอาหารครบหรือไม่ คอยตอบข้อสงสัยเรื่องอาหาร'),
(2, '08:30 น.', 'ออกเดินทางสู่วัดเซนโซจิ (วัดอาซากุสะ)', 'วัดเซนโซจิ (Sensoji Temple)', 'ถ่ายภาพกับโคมไฟสีแดงขนาดยักษ์ และช้อปปิ้งของที่ระลึกที่ถนนนากามิเสะ', 'เน้นย้ำจุดนัดพบตรงเสาโคมแดงใหญ่ และเวลานัดขึ้นรถบัส 10:30 น. (ระวังลูกทัวร์หลงทางในตลาด)'),
(2, '11:00 น.', 'ชมวิวเมืองโตเกียวจากตึกโตเกียวสกายทรี', 'Tokyo Skytree (ชั้น 350)', 'ชมทิวทัศน์แบบ 360 องศาของมหานครโตเกียว', 'หัวหน้าทัวร์ถือตั๋วกรุ๊ป ไปที่เคาน์เตอร์บัตรกรุ๊ปด้านล่างเพื่อแลกบัตรแข็งก่อนพาลูกทัวร์ขึ้น'),
(2, '12:30 น.', 'รับประทานอาหารกลางวัน (ชาบู ชาบู บุฟเฟต์)', 'ร้านอาหารย่านอาซากุสะ', 'เนื้อวัวและเนื้อหมูสไลด์พรีเมียมพร้อมน้ำซุปสูตรดั้งเดิม', 'เช็คความพึงพอใจของอาหาร และแจ้งร้านหากมีท่านที่ไม่ทานเนื้อวัว (ตรวจสอบรายการแพ้อาหารล่วงหน้า)'),
(2, '14:30 น.', 'ช้อปปิ้งและถ่ายรูปกับห้าแยกชิบูย่า', 'ย่านชิบูย่า (Shibuya Crossing & Hachiko)', 'ชมรูปปั้นสุนัขฮาจิโกะผู้ซื่อสัตย์ และช้อปปิ้งห้างชื่อดัง', 'แจ้งจุดนัดพบที่หน้าสถานีชิบูย่า ฝั่งรูปปั้นฮาจิโกะ หรือหน้าตึก Shibuya TSUTAYA 17:30 น.'),
(2, '18:00 น.', 'รับประทานอาหารเย็นอิสระ และเดินทางกลับโรงแรม', 'ย่านชินจูกุ / โรงแรม', 'ให้ลูกทัวร์ได้เลือกทานอาหารเย็นตามความสนใจในย่านชินจูกุ', 'แนะนำร้านอาหารอร่อยๆ ย่านรอบโรงแรมให้ลูกทัวร์ เช่น ร้านราเมงข้อสอบ ร้านเทมปุระ');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(3, '07:30 น.', 'รับประทานอาหารเช้าและเตรียมเช็คเอาท์', 'โรงแรม Shinjuku Granbell Hotel', 'ตรวจสอบความเรียบร้อย ขนสัมภาระขึ้นรถบัส', 'ย้ำลูกทัวร์ห้ามลืมสิ่งของในห้องนอน โดยเฉพาะตู้เซฟและสายชาร์จแบตเตอรี่ คืนคีย์การ์ดครบถ้วน'),
(3, '08:30 น.', 'มุ่งหน้าสู่ภูเขาไฟฟูจิ', 'ทางด่วนชูโอ (Chuo Expressway)', 'ระยะทางเดินทางประมาณ 2 ชั่วโมง ชมธรรมชาติข้างทาง', 'ชวนพูดคุย บรรยายประวัติภูเขาไฟฟูจิ และเช็คสภาพอากาศชั้น 5 ของฟูจิผ่านเว็บกล้องสด'),
(3, '10:30 น.', 'เที่ยวชมภูเขาไฟฟูจิ ชั้น 5 (ขึ้นอยู่กับสภาพอากาศ)', 'ภูเขาไฟฟูจิ ชั้น 5', 'สัมผัสอากาศหนาวเย็นที่ความสูงกว่า 2,305 เมตร ชมศาลเจ้าโคมิตาเคะ', 'หากทางขึ้นปิดเนื่องจากลมแรงหรือน้ำแข็งเกาะ จะเปลี่ยนโปรแกรมไปที่ "ศูนย์ข้อมูลภูเขาไฟฟูจิ" แทน'),
(3, '12:30 น.', 'รับประทานอาหารกลางวัน (เซ็ตเซนโฮโตแบบพื้นบ้าน)', 'ร้านอาหารรอบทะเลสาบคาวากุจิโกะ', 'อุด้งเส้นแบนในซุปมิโซะใส่ผักและฟักทอง เมนูขึ้นชื่อของจังหวัดยามานาชิ', 'อาหารเสิร์ฟร้อนในหม้อเหล็กหล่อ เตือนลูกทัวร์ระวังความร้อนของหม้อ'),
(3, '14:30 น.', 'ถ่ายภาพมุมมหาชน ณ เจดีย์แดงชูเรโต', 'ศาลเจ้าอาราคูระเซนเกน (Chureito Pagoda)', 'เดินบันได 398 ขั้นเพื่อชมวิวเจดีย์ห้าชั้นที่มีฉากหลังเป็นภูเขาไฟฟูจิสวมหมวกหิมะ', 'จุดนี้เดินเหนื่อยและมีบันไดชัน คอยช่วยเหลือและดูแลผู้สูงอายุอย่างใกล้ชิด หรือให้พักรอที่ศาลาด้านล่างหากไม่ไหว'),
(3, '17:00 น.', 'เช็คอินโรงแรมรีสอร์ทออนเซ็น และรับประทานอาหารเย็นบุฟเฟต์ขาปูยักษ์', 'โรงแรม Fuji Premium Resort', 'แช่น้ำแร่ธรรมชาติสไตล์ญี่ปุ่น (Onsen) และอิ่มอร่อยกับเมนูขาปูยักษ์แบบไม่อั้น', 'อธิบายกฎระเบียบและวิธีการแช่ออนเซ็นที่ถูกต้องให้ลูกทัวร์ฟังบนรถก่อนถึงโรงแรม แจ้งเวลานัดรับประทานอาหารเย็น 18:30 น.');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(4, '07:30 น.', 'ทานอาหารเช้า เช็คเอาท์ออกเดินทางสู่สถานีมิชิมะ', 'สถานีรถไฟมิชิมะ (Mishima Station)', 'เดินทางเพื่อขึ้นรถไฟหัวกระสุน ชินคันเซ็น', 'แจกตั๋วรถไฟชินคันเซ็นให้ลูกทัวร์เก็บไว้กับตัว ย้ำห้ามทำหายเด็ดขาด เพราะต้องใช้ตรวจทั้งตอนเข้าและออก'),
(4, '10:15 น.', 'นั่งรถไฟชินคันเซ็นมุ่งสู่เกียวโต เที่ยวรถด่วน Shinkansen Kodama', 'รถไฟชินคันเซ็น (ความเร็ว 285 กม./ชม.)', 'ประสบการณ์ความเร็วที่เสถียรที่สุดในโลก (ใช้เวลาประมาณ 2 ชั่วโมง)', 'ดูแลลูกทัวร์ยกกระเป๋าขึ้นชั้นวางของ ย้ำเวลาสถานีจอดรถไฟมีเวลาขึ้นลงสั้นมาก (ประมาณ 1 นาที) ต้องเตรียมพร้อมก่อนถึงสถานีเกียวโต'),
(4, '12:30 น. (โดยประมาณ)', 'เดินทางถึงสถานีเกียวโต และรับประทานอาหารกลางวัน (เซ็ตเบนโตะเต้าหู้และเทมปุระเกียวโต)', 'ร้านอาหารบริเวณสถานีเกียวโต', 'อาหารญี่ปุ่นโบราณสไตล์เกียวโตแท้ๆ คัดสรรวัตถุดิบสะอาดปราณีต', 'พบรถบัสคันใหม่ของฝั่งคันไซที่ลานจอดรถสถานีเกียวโต โอนถ่ายสัมภาระขึ้นรถบัสคันใหม่'),
(4, '14:30 น.', 'เข้าชมวัดคินคะคุจิ (วัดทองเกียวโต)', 'วัดคินคะคุจิ (Kinkakuji Temple)', 'ปราสาททองคำสามชั้นสะท้อนเงาบนสระน้ำกระจก (สระเคียวโกะจิ)', 'จุดถ่ายรูปหน้าวัดคนจะแน่นมาก แนะนำจุดถ่ายภาพที่สวยและปลอดคนให้ลูกทัวร์'),
(4, '16:30 น.', 'เช็คอินโรงแรมในเมืองเกียวโต', 'โรงแรม Kyoto Century Hotel', 'โรงแรมระดับพรีเมียมใกล้สถานีเกียวโต เดินทางสะดวกสบาย', 'เช็คอินกลุ่มรับคีย์การ์ด ชี้แจงเส้นทางการเดินไปแหล่งช้อปปิ้งรอบสถานีเกียวโต (ห้าง Porta, Yodobashi)'),
(4, '18:30 น.', 'รับประทานอาหารเย็น ณ ร้านอาหารของโรงแรม', 'ห้องอาหารเซ็นจูรี่ เกียวโต', 'บุฟเฟต์นานาชาติพรีเมียมพร้อมเนื้อย่างและซูชิทำสดใหม่', 'นัดหมายเวลารถออกพรุ่งนี้เช้า 09:00 น. พักผ่อนตามอัธยาศัย');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(5, '08:00 น.', 'รับประทานอาหารเช้า ณ โรงแรม', 'Kyoto Century Hotel', 'บุฟเฟต์อาหารเช้าพรีเมียม', 'ทักทายลูกทัวร์ตอนเช้าและตรวจเช็คความพร้อมเรื่องเสื้อผ้าและหมวกเนื่องจากต้องเดินกลางแจ้งค่อนข้างเยอะ'),
(5, '09:15 น.', 'เที่ยวชมศาลเจ้าเสาแดง ฟูชิมิอินาริ', 'ศาลเจ้าฟูชิมิอินาริ (Fushimi Inari Shrine)', 'เดินลอดอุโมงค์เสาโทริอิสีแดงส้มนับหมื่นต้น และขอพรเทพเจ้าสุนัขจิ้งจอก', 'อธิบายลูกทัวร์ว่าไม่จำเป็นต้องเดินขึ้นไปจนถึงยอดเขาเพราะใช้เวลากว่า 2-3 ชั่วโมง ให้เดินถึงแค่จุดทางแยก Senbon Torii แล้วย้อนกลับ นัดขึ้นรถเวลา 11:15 น.'),
(5, '12:00 น.', 'รับประทานอาหารกลางวัน (ข้าวหน้าปลาไหลเกียวโตสูตรโบราณ)', 'ร้านอาหารย่านวัดน้ำใส', 'ปลาไหลย่างเตาถ่านหอมๆ ราดซอสสูตรพิเศษรสชาติกลมกล่อม', 'เช็คอาหารทดแทนสำหรับท่านที่ไม่ทานปลาไหล (เปลี่ยนเป็นข้าวหน้าหมูทอดทงคัตสึที่ประสานงานไว้ล่วงหน้า)'),
(5, '13:30 น.', 'เที่ยวชมวัดน้ำใส คิโยมิสึเดระ และช้อปปิ้งถนนสายกาน้ำชา', 'วัดคิโยมิสึเดระ (Kiyomizu-dera Temple)', 'ชมวิหารไม้หลังใหญ่ที่สร้างโดยไม่ใช้ตะปูสักตัว ดื่มน้ำศักดิ์สิทธิ์สามสายจากน้ำตกโอโตวะ', 'เนื่องจากทางเดินขึ้นวัดเป็นเนินลาดชัน คอยสังเกตผู้สูงอายุ นัดขึ้นรถที่ลานจอดรถบัสชั้นล่างเวลา 16:00 น.'),
(5, '16:30 น.', 'เดินชมถนนสายประวัติศาสตร์ ย่านเกอิชา กิออน', 'ย่านกิออน (Gion Hanami-koji)', 'ชมสถาปัตยกรรมโรงน้ำชาโบราณ อาจมีโอกาสพบเกอิชาหรือไมโกะเดินผ่าน', 'เตือนลูกทัวร์เรื่องกฎหมายห้ามถ่ายภาพเกอิชา/ไมโกะบนถนนส่วนบุคคล (มีป้ายเตือนและค่าปรับ 10,000 เยน) ให้ถ่ายเฉพาะทิวทัศน์รอบนอก'),
(5, '18:30 น.', 'รับประทานอาหารค่ำ (มื้อส่งท้าย: ปิ้งย่างยากินิกุเนื้อวัววากิวพรีเมียม)', 'ร้านปิ้งย่างเกียวโต', 'ลิ้มลองเนื้อวัวละลายในปาก พร้อมเครื่องเคียงและเครื่องดื่มเบียร์/ซอฟต์ดริ้งก์', 'บรรยากาศรื่นเริงขอบคุณลูกทัวร์ กล่าวปิดทริปและชี้แจงการจัดกระเป๋าเตรียมตัวเดินทางกลับสนามบินคันไซในคืนถัดไป');
INSERT INTO itinerary_events (itinerary_id, time, activity, location, highlight, guide_note) VALUES
(6, '08:30 น.', 'รับประทานอาหารเช้า เช็คเอาท์ และขนสัมภาระขึ้นรถบัส', 'Kyoto Century Hotel', 'เช็คเอาท์อย่างเป็นทางการ', 'เก็บเอกสารใบเสร็จจากโรงแรม และคืนกุญแจห้องพักครบถ้วน ย้ำตรวจสอบของมีค่ารอบสุดท้าย'),
(6, '09:30 น.', 'เดินทางสู่ห้างอิออน มอลล์ คันไซ พลาซ่า เพื่อช้อปปิ้งของฝากส่งท้าย', 'AEON Mall Rinku Sennan', 'แหล่งรวมแบรนด์เนม ขนม และเครื่องสำอางชั้นนำ ใกล้สนามบินคันไซ', 'แจกแผ่นพับคูปองส่วนลดของห้างอิออน แนะนำจุดแลกเงินเยนที่เหลือและบริการเคลมภาษี (Tax Refund) นัดพบ 14:00 น.'),
(6, '12:00 น.', 'รับประทานอาหารกลางวันอิสระภายในห้างอิออน มอลล์', 'ศูนย์อาหารและโซนร้านอาหารของห้าง', 'ช้อปปิ้งและทานอาหารตามอัธยาศัย มีร้านอาหารหลากหลายกว่า 50 ร้าน', 'สแตนด์บายแถวศูนย์อาหาร คอยช่วยประสานงานกรณีลูกทัวร์มีข้อสงสัยหรือซื้อของแลกเหรียญ'),
(6, '14:30 น.', 'เดินทางสู่สนามบินคันไซ ตรวจเช็คเอกสารขากลับ', 'ท่าอากาศยานนานาชาติคันไซ (KIX)', 'จัดเตรียมสัมภาระสำหรับเช็คอินไฟลท์บินกลับไทย', 'พาลูกทัวร์ไปชั่งน้ำหนักกระเป๋าที่จุดชั่งน้ำหนักสาธารณะก่อนเข้าเช็คอิน เพื่อลดปัญหาหน้าเคาน์เตอร์'),
(6, '21:00 น.', 'เช็คอินเคาน์เตอร์ Japan Airlines โหลดกระเป๋า', 'สนามบินคันไซ ชั้น 4 แถว G', 'ผ่านด่าน ตม. ขาออก ช้อปปิ้งดิวตี้ฟรีในสนามบินส่งท้าย', 'แจกบอร์ดดิ้งพาสให้ลูกทัวร์ทุกคน ย้ำเรื่องสิ่งของต้องห้ามถือขึ้นเครื่อง (ของเหลวเกิน 100ml, ของมีคม)'),
(6, '00:55 น. (+1)', 'เหินฟ้ากลับสู่กรุงเทพฯ เที่ยวบิน JL727', 'บนเครื่องบิน JL727', 'เดินทางถึงกรุงเทพฯ เวลาประมาณ 05:00 น. ของเช้าวันถัดไปโดยสวัสดิภาพ', 'ดูแลความเรียบร้อยก่อนเครื่องขึ้น เมื่อถึงสุวรรณภูมิยืนส่งลูกทัวร์และช่วยเช็คความเรียบร้อยของกระเป๋าเดินทางที่สายพานรับกระเป๋า');
INSERT INTO vouchers (id, tour_id, category, title, subtitle, reference_code, valid_date, details_html) VALUES
(
INSERT INTO contacts (tour_id, category, name, role, phone, line_id, note) VALUES
('JP-TFK-0924', 'ไกด์และคนขับรถท้องถิ่น (Local Team)', 'คุณเค็นจิ ซาโต้ (Kenji Sato)', 'ไกด์ท้องถิ่นญี่ปุ่น (พูดภาษาไทยได้)', '+81-90-1234-5678', 'kenji_guide_jp', 'รอรับกรุ๊ปทัวร์ที่สนามบินนาริตะ ประตูขาออกที่ 2 วันแรก'),
('JP-TFK-0924', 'ไกด์และคนขับรถท้องถิ่น (Local Team)', 'คุณทานากะ ซัง (Mr. Tanaka)', 'คนขับรถบัสคันที่ 1 (ช่วงโตเกียว - ฟูจิ - มิชิมะ)', '+81-80-8765-4321', '-', 'รถบัสสีขาว ทะเบียนรถโตเกียว 230-U-8899'),
('JP-TFK-0924', 'ไกด์และคนขับรถท้องถิ่น (Local Team)', 'คุณยามาโมโตะ ซัง (Mr. Yamamoto)', 'คนขับรถบัสคันที่ 2 (ช่วงคันไซ - เกียวโต - โอซาก้า)', '+81-90-9876-5432', '-', 'รถบัสสีน้ำเงิน ทะเบียนรถเกียวโต 100-W-7788'),
('JP-TFK-0924', 'คู่ค้าและสำนักงานใหญ่ (HQ & Partners)', 'บริษัท แฮปปี้ ทราเวล แอนด์ ทัวร์ (Happy Travel HQ)', 'สำนักงานใหญ่ กรุงเทพฯ (ประสานงานทั่วไป)', '02-123-4567 / 081-999-8888', '@happytravel', 'ติดต่อฝ่ายปฏิบัติการกรุ๊ปทัวร์ต่างประเทศ (ติดต่อได้ 24 ชม. กรณีฉุกเฉิน)'),
('JP-TFK-0924', 'คู่ค้าและสำนักงานใหญ่ (HQ & Partners)', 'JTB Global Travel Service (Japan Partner)', 'เอเย่นต์ท้องถิ่นประเทศญี่ปุ่น (แลนด์ญี่ปุ่น)', '+81-3-3344-5566', '-', 'กรณีติดปัญหาเรื่องห้องพักโรงแรม หรือรถบัสมารับล่าช้า'),
('JP-TFK-0924', 'ความปลอดภัยและกรณีฉุกเฉิน (Emergency Contacts)', 'สถานเอกอัครราชทูตไทย ณ กรุงโตเกียว (Royal Thai Embassy)', 'ความช่วยเหลือด้านกฎหมาย พาสปอร์ตหาย หรือเหตุฉุกเฉิน', '+81-3-5789-2433', '-', 'พิกัด: 3-14-6 Kami-Osaki, Shinagawa-ku, Tokyo (สายด่วนฉุกเฉิน: +81-90-2561-1391)'),
('JP-TFK-0924', 'ความปลอดภัยและกรณีฉุกเฉิน (Emergency Contacts)', 'ศูนย์บริการทางการแพทย์สำหรับนักท่องเที่ยวญี่ปุ่น (JNTO)', 'สายด่วนข้อมูลโรงพยาบาลและการแปลภาษาแพทย์', '050-3816-2720', '-', 'โทรฟรีในญี่ปุ่น ให้บริการข้อมูลโรงพยาบาลที่มีล่ามภาษาไทย'),
('JP-TFK-0924', 'ความปลอดภัยและกรณีฉุกเฉิน (Emergency Contacts)', 'บริษัทประกันภัยการเดินทาง (MSIG Assist)', 'ประสานงานเคลมประกันสุขภาพและการเจ็บป่วยต่างประเทศ', '+66-2-696-3696', '-', 'หมายเลขกรมธรรม์กลุ่มของกรุ๊ปทัวร์: MSIG-TRAVEL-2026-99');
